import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int dilation
) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int output_pos = threadIdx.x;

    if (batch_idx >= batch_size || channel_idx >= out_channels || output_pos >= output_length) {
        return;
    }

    // Each thread handles one output position for one batch and channel
    int input_start_pos = output_pos * stride;

    // Accumulate over input channels and kernel positions
    float sum = 0.0f;

    for (int k = 0; k < kernel_size; ++k) {
        int input_pos = input_start_pos + k * dilation;

        // Check bounds
        if (input_pos >= 0 && input_pos < input_length) {
            for (int c = 0; c < in_channels; ++c) {
                int input_idx = batch_idx * (in_channels * input_length) +
                               c * input_length +
                               input_pos;

                int weight_idx = channel_idx * (in_channels * kernel_size) +
                                c * kernel_size +
                                k;

                sum += (float)input[input_idx] * (float)weight[weight_idx];
            }
        }
    }

    int output_idx = batch_idx * (out_channels * output_length) +
                     channel_idx * output_length +
                     output_pos;

    output[output_idx] = __float2half(sum);
}

// Wrapper function to launch kernel
extern "C" void launch_conv1d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int dilation
) {
    dim3 grid(batch_size, out_channels);
    dim3 block(output_length);

    conv1d_kernel<<<grid, block>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_length, output_length,
        kernel_size, stride, dilation
    );

    cudaDeviceSynchronize();
}
"""

# Python wrapper class
class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.dilation = dilation
        self.bias = bias

        # Initialize weights
        self.weight = torch.nn.Parameter(torch.randn(out_channels, in_channels, kernel_size, dtype=torch.float16))
        if bias:
            self.bias = torch.nn.Parameter(torch.randn(out_channels, dtype=torch.float16))
        else:
            self.register_parameter('bias', None)

        # Compile CUDA extension
        self.conv_op = load_inline(
            name="conv1d_ext",
            cpp_sources=cuda_source,
            cuda_sources=cuda_source,
            functions=["launch_conv1d"],
            verbose=False
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, _, input_length = x.shape

        # Calculate output length
        output_length = (input_length + 2 * 0 - (self.dilation * (self.kernel_size - 1) + 1)) // self.stride + 1

        # Create output tensor
        output = torch.empty(batch_size, self.out_channels, output_length, dtype=torch.float16, device=x.device)

        # Launch CUDA kernel
        self.conv_op.launch_conv1d(
            x.contiguous().data_ptr(),
            self.weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            self.out_channels,
            input_length,
            output_length,
            self.kernel_size,
            self.stride,
            self.dilation
        )

        # Add bias if present
        if self.bias is not None:
            output = output + self.bias.view(1, -1, 1)

        return output

